import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

def task_func(column, data):
    if not data:
        raise ValueError("The data list is empty.")

    df = pd.DataFrame(data)

    def resolve_col(name):
        if name in df.columns:
            return name
        lower_map = {str(c).lower(): c for c in df.columns}
        return lower_map.get(str(name).lower())

    resolved_column = resolve_col(column)
    if resolved_column is None:
        raise KeyError(column)

    required_check_cols = ["steps", "calories burned", "distance walked"]
    for req in required_check_cols:
        resolved_req = resolve_col(req)
        if resolved_req is None:
            raise KeyError(req)
        numeric_vals = pd.to_numeric(df[resolved_req], errors="coerce")
        if (numeric_vals < 0).any():
            raise ValueError("Numeric values for steps, calories burned, and distance walked must be non-negative.")

    date_col = resolve_col("Date")
    if date_col is None:
        raise KeyError("Date")

    series = pd.to_numeric(df[resolved_column], errors="coerce")

    stats = {
        "sum": series.sum(),
        "mean": series.mean(),
        "min": series.min(),
        "max": series.max(),
    }

    fig, ax = plt.subplots()
    ax.plot(df[date_col], series)
    ax.set_xlabel("Date")
    ax.set_ylabel(column)
    ax.set_title(f"Line Chart of {column}")

    return stats, ax
